package demo.examples

import demo.CatalogEntry
import demo.Groups
import echarts.*
import echarts.options.*
import js.objects.unsafeJso

/*
 * Line examples whose data is generated by a formula instead of being a fixed table.
 *
 * Dropped on purpose: `line-easing` samples every easing function of zrender (about 30 series of
 * 2000 points), `line-pen` needs pointer events, `line-draggable` a real drag.
 */

private val lineExtra = Category(Groups.LINE, "examples/LineExtra.kt")

/** The `[r, theta]` spiral of `line-polar`. */
private fun polarSpiral(): Array<LineDataItem?> {
    val data = Array(101) { index ->
        val theta = index / 100.0 * 360
        val r = 5 * (1 + kotlin.math.sin(theta / 180 * kotlin.math.PI))
        doubleArrayOf(r, theta)
    }
    return points(*data)
}

/** The `[r, i]` curve of `line-polar2`. */
private fun polarRose(): Array<LineDataItem?> {
    val data = Array(361) { index ->
        val t = index / 180.0 * kotlin.math.PI
        doubleArrayOf(kotlin.math.sin(2 * t) * kotlin.math.cos(2 * t), index.toDouble())
    }
    return points(*data)
}

/** The product of three sines of `line-function`, sampled every 0.1. */
private fun functionPlot(): Array<LineDataItem?> {
    val data =
        (0..4000).map { step ->
            val x = -200 + step * 0.1
            val scaled = x / 10
            val y =
                kotlin.math.sin(scaled) *
                    kotlin.math.cos(scaled * 2 + 1) *
                    kotlin.math.sin(scaled * 3 + 2) * 50
            doubleArrayOf(x, y)
        }
    return points(*data.toTypedArray())
}

